    SELECT qty_incur INTO current_qty
    FROM tpurchase_in
    WHERE lotin_id = NEW.tpurchase_in_lotin_id;

    
    IF current_qty < NEW.qty_use THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = '사용량이 재고량보다 큽니다.';
    ELSE
        UPDATE tpurchase_in
        SET qty_incur = qty_incur - NEW.qty_use
        WHERE lotin_id = NEW.tpurchase_in_lotin_id;
    END IF;
END */;;
